/* From Uiverse.io by Yaya12085 - Tags: card, product, modern, pack, plan */
.__UIV_SCOPE__ .plan {
  border-radius: 16px;
  box-shadow: 0 30px 30px -25px rgba(0, 38, 255, 0.205);
  padding: 10px;
  background-color: #fff;
  color: #697e91;
  max-width: 300px;
}

.__UIV_SCOPE__ .plan strong {
  font-weight: 600;
  color: #425275;
}

.__UIV_SCOPE__ .plan .inner {
  align-items: center;
  padding: 20px;
  padding-top: 40px;
  background-color: #ecf0ff;
  border-radius: 12px;
  position: relative;
}

.__UIV_SCOPE__ .plan .pricing {
  position: absolute;
  top: 0;
  right: 0;
  background-color: #bed6fb;
  border-radius: 99em 0 0 99em;
  display: flex;
  align-items: center;
  padding: 0.625em 0.75em;
  font-size: 1.25rem;
  font-weight: 600;
  color: #425475;
}

.__UIV_SCOPE__ .plan .pricing small {
  color: #707a91;
  font-size: 0.75em;
  margin-left: 0.25em;
}

.__UIV_SCOPE__ .plan .title {
  font-weight: 600;
  font-size: 1.25rem;
  color: #425675;
}

.__UIV_SCOPE__ .plan .title + * {
  margin-top: 0.75rem;
}

.__UIV_SCOPE__ .plan .info + * {
  margin-top: 1rem;
}

.__UIV_SCOPE__ .plan .features {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .plan .features li {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.__UIV_SCOPE__ .plan .features li + * {
  margin-top: 0.75rem;
}

.__UIV_SCOPE__ .plan .features .icon {
  background-color: #1FCAC5;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  border-radius: 50%;
  width: 20px;
  height: 20px;
}

.__UIV_SCOPE__ .plan .features .icon svg {
  width: 14px;
  height: 14px;
}

.__UIV_SCOPE__ .plan .features + * {
  margin-top: 1.25rem;
}

.__UIV_SCOPE__ .plan .action {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: end;
}

.__UIV_SCOPE__ .plan .button {
  background-color: #6558d3;
  border-radius: 6px;
  color: #fff;
  font-weight: 500;
  font-size: 1.125rem;
  text-align: center;
  border: 0;
  outline: 0;
  width: 100%;
  padding: 0.625em 0.75em;
  text-decoration: none;
}

.__UIV_SCOPE__ .plan .button:hover, .__UIV_SCOPE__ .plan .button:focus {
  background-color: #4133B7;
}
